"""MLflow experiment tracker for alignment evaluation.

Thin adapter that logs AlignmentMetrics to MLflow for experiment comparison.
DuckDB remains the source of truth — MLflow is used only for visualization.
"""

from __future__ import annotations

import json
import tempfile
from datetime import datetime
from pathlib import Path
from typing import TYPE_CHECKING

from src.lib.config import settings
from src.lib.logging import get_logger

if TYPE_CHECKING:
    from src.services.alignment.evaluator import AlignmentMetrics

logger = get_logger(__name__)

try:
    import mlflow

    MLFLOW_AVAILABLE = True
except ImportError:
    MLFLOW_AVAILABLE = False
    logger.debug("mlflow not installed — tracking disabled")


def is_tracking_available() -> bool:
    """Check if MLflow is installed."""
    return MLFLOW_AVAILABLE


def get_alignment_params() -> dict[str, str | float | int]:
    """Extract current alignment parameters from config for experiment logging."""
    return {
        "model_version": "aeneas-dtw-1.0",
        "tts_engine": settings.get("alignment.tts_engine", "espeak"),
        "task_language": settings.get("alignment.task_language", "eng"),
        "audio_sample_rate": settings.get("alignment.audio_sample_rate", 16000),
        "audio_channels": settings.get("alignment.audio_channels", 1),
        "min_confidence_threshold": settings.get("alignment.min_confidence_threshold", 0.90),
        "max_gap_seconds": settings.get("alignment.max_gap_seconds", 5.0),
        "boundary_algorithm": settings.get("alignment.boundary_algorithm", "auto"),
        "mfcc_window": settings.get("alignment.mfcc_window", "default"),
        "dtw_margin": settings.get("alignment.dtw_margin", "default"),
    }


def log_experiment_run(
    metrics: AlignmentMetrics,
    report: str,
    params: dict[str, str | float | int] | None = None,
    run_name: str | None = None,
    experiment_name: str | None = None,
) -> str | None:
    """Log an evaluation run to MLflow.

    Args:
        metrics: Computed AlignmentMetrics from evaluator.
        report: Human-readable report string.
        params: Override alignment params (default: auto-detected from config).
        run_name: Optional run name (default: auto-generated).
        experiment_name: Override experiment name from config.

    Returns:
        MLflow run_id if logged, None if tracking unavailable.
    """
    if not MLFLOW_AVAILABLE:
        logger.warning("mlflow not installed — skipping tracking")
        return None

    exp_name = experiment_name or settings.get("tracking.experiment_name", "alignment-tuning")
    tracking_uri = settings.get("tracking.mlflow_uri", "mlruns")

    mlflow.set_tracking_uri(tracking_uri)
    mlflow.set_experiment(exp_name)

    resolved_params = params or get_alignment_params()

    if run_name is None:
        ts = datetime.now().strftime("%Y%m%d-%H%M%S")
        run_name = f"{resolved_params.get('model_version', 'unknown')}-{ts}"

    with mlflow.start_run(run_name=run_name) as run:
        mlflow.log_params({k: str(v) for k, v in resolved_params.items()})

        mlflow.log_metrics({
            "total_verses": float(metrics.total_verses),
            "mae_start": metrics.mae_start,
            "mae_end": metrics.mae_end,
            "mean_bias_start": metrics.mean_bias_start,
            "mean_bias_end": metrics.mean_bias_end,
            "max_error_start": metrics.max_error_start,
            "max_error_end": metrics.max_error_end,
            "within_200ms": metrics.within_200ms,
            "within_500ms": metrics.within_500ms,
            "within_1s": metrics.within_1s,
        })

        with tempfile.TemporaryDirectory() as tmpdir:
            report_path = Path(tmpdir) / "evaluation_report.txt"
            report_path.write_text(report)

            position_path = Path(tmpdir) / "per_position_mae.json"
            position_path.write_text(json.dumps(
                {str(k): v for k, v in metrics.per_position_mae.items()}, indent=2
            ))

            run_path = Path(tmpdir) / "per_run_mae.json"
            run_path.write_text(json.dumps(
                {str(k): v for k, v in metrics.per_run_mae.items()}, indent=2
            ))

            mlflow.log_artifacts(tmpdir)

        run_id = run.info.run_id
        logger.info(f"MLflow run logged: {run_id=}, {exp_name=}")
        return run_id
